<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence\PDO;
use App\Domain\Quiz\QuizResult;use App\Domain\Quiz\QuizResultId;use App\Domain\Quiz\QuizResultRepository;use App\Domain\Quiz\QuizSessionId;use PDO;
final class PdoQuizResultRepository implements QuizResultRepository { public function __construct(private PDO $pdo) {} public function nextId(): QuizResultId { return QuizResultId::new(); } public function save(QuizResult $r): void { $st=$this->pdo->prepare('INSERT INTO quiz_results (id,quiz_id,student_name,score,total,percentage,duration,answers_json,created_at) VALUES (:id,:quizId,:studentName,:score,:total,:percentage,:duration,:answersJson,:createdAt)'); $st->execute(['id'=>$r->id()->value(),'quizId'=>$r->quizId()->value(),'studentName'=>$r->studentName(),'score'=>$r->score(),'total'=>$r->total(),'percentage'=>$r->percentage(),'duration'=>$r->duration(),'answersJson'=>$r->answersJson(),'createdAt'=>$r->createdAt()->format(DATE_ATOM)]); } public function listByQuiz(QuizSessionId $quizId): array { $st=$this->pdo->prepare('SELECT * FROM quiz_results WHERE quiz_id=:id ORDER BY created_at DESC'); $st->execute(['id'=>$quizId->value()]); $rows=$st->fetchAll(); return array_map(fn(array $r)=>QuizResult::reconstitute(QuizResultId::fromString((string)$r['id']),QuizSessionId::fromString((string)$r['quiz_id']),(string)$r['student_name'],(int)$r['score'],(int)$r['total'],(float)$r['percentage'],(int)$r['duration'],(string)$r['answers_json'],new \DateTimeImmutable((string)$r['created_at'])),$rows); }}
